output_text:
[
  {
    "id": "must_return_cart_to_corral",
    "text": "A shopper who enters the store is obliged to return the cart to the top-left cart corral before leaving.",
    "abstraction": {
      "state_properties": {
        "return_corral": "at(0,1)",
        "cart_parked_in_return_corral": "cartAt(0,1)"
      },
      "events": {
        "return_cart_to_corral": {
          "pre": {
            "and": [
              "return_corral",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return_corral"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_to_corral"
    }
  },
  {
    "id": "no_leaving_cart_outside_corral",
    "text": "It is forbidden to leave a cart anywhere except the top-left return corral.",
    "abstraction": {
      "state_properties": {
        "return_corral": "at(0,1)"
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "LEAVE_CART",
          {
            "not": "return_corral"
          }
        ]
      }
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "A shopper may exit only once the cart is already parked in the return corral.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "cart_returned"
          }
        ]
      }
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "At the start of a shopping trip, the shopper is obliged to take the cart from the entrance cart station.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_waiting_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_waiting_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "items_only_with_cart",
    "text": "It is forbidden to pick up shelf items unless the shopper is currently pushing or holding the cart.",
    "abstraction": {
      "state_properties": {
        "cart_in_possession": "hasCart"
      },
      "events": {
        "pickup_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "cart_in_possession"
          }
        ]
      }
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "It is forbidden to carry groceries by hand rather than placing them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_only_at_product_bays",
    "text": "Shelf-item pickup is allowed only at recognized product-bay positions, abstracting over the upper and lower shelf fronts for each product.",
    "abstraction": {
      "state_properties": {
        "apple_bay": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_bay": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_bay": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_bay": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "product_bay": {
          "or": [
            "apple_bay",
            "bread_bay",
            "milk_bay",
            "eggs_bay"
          ]
        }
      },
      "events": {
        "product_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "product_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "PICKUP_ITEM",
          {
            "not": "product_bay"
          }
        ]
      }
    }
  },
  {
    "id": "top_left_interaction_is_cart_return",
    "text": "The top-left station is a cart-return corral, so interacting there for any purpose other than leaving the cart is forbidden.",
    "abstraction": {
      "state_properties": {
        "return_corral": "at(0,1)"
      },
      "events": {
        "non_return_interaction_at_corral": {
          "pre": {
            "and": [
              "return_corral",
              "INTERACT",
              {
                "not": "LEAVE_CART"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "non_return_interaction_at_corral"
    }
  }
]
